    "requirements": "<ul>\n            <li>Tốt nghiệp Đại học chuyên ngành Kinh tế, Quản trị kinh doanh, Ngoại ngữ hoặc ngành liên quan.</li>\n            <li>Kỹ năng lập kế hoạch, quản lý thời gian và kỹ năng giao tiếp tốt.</li>\n            <li>Sử dụng thành thạo tin học văn phòng (Word, Excel, PowerPoint).</li>\n            <li>Tinh thần trách nhiệm cao, năng động và cẩn thận trong công việc.</li>\n          </ul>",
