    "requirements": "<ul>\n            <li>Tốt nghiệp Đại học/Cao đẳng khối ngành Kinh tế, Tài chính, Ngân hàng, Quản trị kinh doanh hoặc liên quan.</li>\n            <li>Ngoại hình sáng, giao tiếp tự tin, giọng nói truyền cảm, không nói ngọng/lắp.</li>\n            <li>Kỹ năng xử lý tình huống khéo léo, cẩn thiện, trung thực và chịu khó.</li>\n            <li>Sử dụng tốt các công cụ văn phòng (Word, Excel).</li>\n          </ul>",
    "benefits": "<ul>\n            <li>Lương cứng cạnh tranh + thưởng doanh số vượt KPI hấp dẫn hàng tháng/quý.</li>\n            <li>Được đào tạo nghiệp vụ ngân hàng chuyên nghiệp trước khi nhận việc.</li>\n            <li>Bảo hiểm sức khỏe Aon Care và các chế độ phúc lợi sinh nhật, nghỉ mát hàng năm.</li>\n          </ul>",
