    "description": "<ul>\n            <li>Chủ động tìm kiếm, tiếp cận và phát triển danh mục khách hàng cá nhân hoặc doanh nghiệp tiềm năng.</li>\n            <li>Tư vấn, thiết kế giải pháp tài chính phù hợp: cho vay thế chấp/tín chấp, thẻ tín dụng, tiền gửi, bảo hiểm.</li>\n            <li>Thẩm định hồ sơ khách hàng, phân tích năng lực tài chính và lập tờ trình trình cấp phê duyệt tín dụng.</li>\n            <li>Theo dõi, giám sát và quản lý dư nợ sau giải ngân để hạn chế phát sinh nợ xấu.</li>\n          </ul>",
    "requirements": "<ul>\n            <li>Tốt nghiệp Đại học chuyên ngành Tài chính - Ngân hàng, Quản trị kinh doanh, Kinh tế hoặc Luật.</li>\n            <li>Có kỹ năng giao tiếp, đàm phán và thuyết phục khách hàng tốt.</li>\n            <li>Chịu được áp lực chỉ tiêu kinh doanh (KPI) cao và năng động trong công việc.</li>\n            <li>Ưu tiên ứng viên có kinh nghiệm RM tại các ngân hàng khác.</li>\n          </ul>",
    "benefits": "<ul>\n            <li>Mức thu nhập không giới hạn (Lương cứng cạnh tranh + hoa hồng doanh số kinh doanh vượt bậc).</li>\n            <li>Môi trường làm việc năng động, lộ trình thăng tiến rõ ràng lên Trưởng nhóm/Trưởng phòng kinh doanh.</li>\n            <li>Đóng bảo hiểm đầy đủ, các hoạt động team-building và nghỉ mát cao cấp thường niên.</li>\n          </ul>",
    "hrEmail": "tuyendung@vpbank.com.vn",
