    "description": "<ul>\n            <li>Đánh giá hồ sơ pháp lý tài sản, rà soát nợ xấu và lập phương án xử lý nợ quá hạn.</li>\n            <li>Tham gia tố tụng tại tòa án hoặc làm việc với các cơ quan thi hành án để thu hồi nợ cho ngân hàng.</li>\n            <li>Soạn thảo, thẩm định các hợp đồng kinh tế và văn bản quy chế nội bộ đảm bảo tính tuân thủ pháp luật.</li>\n            <li>Kiểm toán quy trình nghiệp vụ và cảnh báo rủi ro hoạt động định kỳ.</li>\n          </ul>",
    "requirements": "<ul>\n            <li>Tốt nghiệp Đại học chuyên ngành Luật hoặc Kế toán/Kiểm toán/Tài chính.</li>\n            <li>Am hiểu luật dân sự, luật kinh tế, tố tụng dân sự và các quy định ngành Ngân hàng.</li>\n            <li>Kỹ năng đàm phán, xử lý hồ sơ cẩn thận, chịu được áp lực cao.</li>\n            <li>Ưu tiên ứng viên có kinh nghiệm pháp lý hoặc xử lý nợ từ 1-2 năm trở lên.</li>\n          </ul>",
    "benefits": "<ul>\n            <li>Lương cứng cạnh tranh + phụ cấp xăng xe điện thoại + thưởng hiệu quả thu nợ.</li>\n            <li>Gói bảo hiểm sức khỏe cao cấp của VPBank và đào tạo chuyên sâu pháp luật ngân hàng.</li>\n            <li>Cơ hội thăng tiến và khẳng định năng lực cá nhân trong môi trường chuyên nghiệp.</li>\n          </ul>",
    "hrEmail": "tuyendung@vpbank.com.vn",
